+using System;
+using System.IO;
+using System.Web;
+namespace InformationWeb
+{
+    public static class ImageHelper
+    {
+        public const string DefaultImageUrl = "/Media/logo/logo-main.png";
+        public static string GetImageUrl(object imageObj)
+        {
+            string imageUrl = imageObj == null || imageObj == DBNull.Value ? string.Empty : Convert.ToString(imageObj).Trim();
+            if (string.IsNullOrEmpty(imageUrl))
+            {
+                return DefaultImageUrl;
+            }
+            if (imageUrl.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || imageUrl.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
+            {
+                return imageUrl;
+            }
+            if (imageUrl.StartsWith("/", StringComparison.OrdinalIgnoreCase))
+            {
+                return LocalFileExists(imageUrl) ? imageUrl : DefaultImageUrl;
+            }
+            string mediaUrl = "/Media/Images/" + imageUrl.TrimStart(new char[] { '~', '/' });
+            return LocalFileExists(mediaUrl) ? mediaUrl : DefaultImageUrl;
+        }
+        private static bool LocalFileExists(string imageUrl)
+        {
+            try
+            {
+                HttpContext context = HttpContext.Current;
+                if (context == null)
+                {
+                    return true;
+                }
+                string path = context.Server.MapPath(imageUrl);
+                return File.Exists(path);
+            }
+            catch
+            {
+                return false;
+            }
+        }
+    }
+}
*** End Patch

